<?php $labels=['vehicles'=>'Vehículos','drivers'=>'Repartidores','delivery_runs'=>'Rutas manuales']; ?>
<section class="admin-page-head"><div><p class="admin-kicker">M10 · LOGÍSTICA</p><h1><?= e($labels[$kind]) ?></h1><p>Repartidores sin cuenta de usuario. Rutas y secuencia manuales, sin seguimiento GPS.</p></div><a class="admin-secondary-button" href="/admin/deliveries">Entregas</a></section>
<nav class="admin-panel"><?php foreach($labels as $k=>$label):?><a class="admin-secondary-button" href="?kind=<?= e($k) ?>"><?= e($label) ?></a><?php endforeach?></nav>
<?php if(!$page->items):?><section class="admin-panel"><p>No hay recursos registrados.</p></section><?php endif?>
<?php $forms=array_merge($page->items,[null]);foreach($forms as $resource):?>
<section class="admin-panel"><h2><?= e($resource?'#'.$resource['id'].' · '.$resource['name']:'Registrar recurso') ?></h2>
<?php if($kind==='delivery_runs'&&$resource):?><p><?= e($resource['branch_name'].' · '.$resource['scheduled_date']) ?> · Vehículo #<?= e($resource['vehicle_id']) ?> · Repartidor #<?= e($resource['driver_id']) ?></p></section><?php continue;endif?>
<form method="post" action="/admin/deliveries/resources" class="admin-form"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="kind" value="<?= e($kind) ?>"><input type="hidden" name="operation_key" value="<?= e(bin2hex(random_bytes(20))) ?>"><input type="hidden" name="id" value="<?= e($resource['id']??'') ?>"><input type="hidden" name="lock_version" value="<?= e($resource['lock_version']??'0') ?>">
<div class="admin-form-grid"><label class="admin-field"><span>Sucursal</span><select name="branch_id" required><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= ($resource['branch_id']??'')==$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Nombre / ficha básica</span><input name="name" maxlength="120" value="<?= e($resource['name']??'') ?>" required></label>
<?php if($kind==='delivery_runs'):?><label class="admin-field"><span>Fecha de ruta</span><input type="date" name="scheduled_date" required></label><label class="admin-field"><span>ID de vehículo</span><input name="vehicle_id" inputmode="numeric" required></label><label class="admin-field"><span>ID de repartidor</span><input name="driver_id" inputmode="numeric" required></label><?php else:?><label class="admin-field"><span>Código estable</span><input name="code" value="<?= e($resource['code']??'') ?>" maxlength="40" required></label><?php foreach(['is_active'=>'Estado activo','is_available'=>'Disponible']as $flag=>$label):?><label class="admin-field"><span><?= e($label) ?></span><select name="<?= e($flag) ?>"><option value="1" <?= ($resource[$flag]??1)==1?'selected':'' ?>>Sí</option><option value="0" <?= ($resource[$flag]??1)==0?'selected':'' ?>>No</option></select></label><?php endforeach;endif?></div><button class="admin-primary-button">Guardar recurso</button></form></section><?php endforeach?>
<nav class="admin-pagination"><?php if($page->offset):?><a href="?<?= e(http_build_query(['kind'=>$kind,'offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e(http_build_query(['kind'=>$kind,'offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav>
